  const layer=el('div','vision-settings-layer');layer.hidden=true;
  const panel=el('section','vision-settings');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Vision settings');
  panel.innerHTML='<div class="settings-split-line"></div><aside class="settings-sidebar"><div class="settings-wordmark"><img src="vision-mark.svg" alt=""><span>Vision<span>Settings</span></span></div><nav aria-label="Settings"></nav><div class="settings-profile"></div></aside><div class="settings-main"><header class="settings-heading"><div><h1></h1><p></p></div><button class="settings-close" aria-label="Close settings">'+svg('m6 6 12 12M18 6 6 18')+'</button></header><div class="settings-content"></div><footer class="settings-footer"><span role="status"></span><button class="settings-reload secondary">Refresh</button></footer></div>';
  layer.append(panel);document.body.append(layer);
  const nav=panel.querySelector('nav'),body=panel.querySelector('.settings-content'),status=panel.querySelector('[role=status]');
