  const rpc=(method,params={})=>api('settings/rpc',{method,params});
  const notice=(text,error=false)=>{status.textContent=text;status.classList.toggle('error',error);};
  const button=(text,action,parent=body,cls='secondary')=>{const b=el('button',cls,text);b.type='button';b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await action();}catch(e){if(e.name!=='AbortError'){const local=b.closest('.settings-editor')?.querySelector('.editor-status');if(local)local.textContent=e.message;else notice(e.message,true);}}finally{b.disabled=false;}};parent.append(b);return b;};
  const section=(title,description='',parent=body)=>{const s=el('section','settings-section');if(title)s.append(el('h2','',title));if(description)s.append(el('p','section-description',description));parent.append(s);return s;};
  const empty=(title,description,parent=body)=>{const n=el('div','settings-empty');n.innerHTML=svg('M5 5h14v14H5M9 12h6M12 9v6');n.append(el('h3','',title),el('p','',description));parent.append(n);};
  function row(title,description='',parent=body){const n=el('div','setting-row'),label=el('div','setting-label');label.append(el('h3','',title));if(description)label.append(el('p','',description));const control=el('div','setting-control');n.append(label,control);parent.append(n);return control;}
  function input(title,value='',{description='',parent=body,type='text',multiline=false,onchange}={}){const control=row(title,description,parent),n=el(multiline?'textarea':'input','setting-input');n.value=value??'';n.setAttribute('aria-label',title);if(!multiline)n.type=type;else n.rows=5;if(onchange)n.oninput=()=>onchange(type==='number'?(n.value===''?null:Number(n.value)):n.value);control.append(n);return n;}
