  function facts(data,parent=body){const dl=el('dl','settings-facts');for(const [key,value]of Object.entries(data||{})){if(value===null||value===undefined||/secret|token|key|path|session_id/i.test(key))continue;if(typeof value==='object'){const values=Array.isArray(value)?value:Object.entries(value).map(([k,v])=>typeof v==='object'?null:pretty(k)+': '+v).filter(Boolean);if(values.some(v=>typeof v==='object'))continue;dl.append(el('dt','',pretty(key)),el('dd','',values.join(', ')));}else dl.append(el('dt','',pretty(key)),el('dd','',typeof value==='boolean'?(value?'Enabled':'Disabled'):String(value)));}parent.append(dl);}
