    const opener=document.activeElement,overlay=el('div','vision-modal-layer settings-editor-layer'),dialog=el('section','vision-dialog settings-editor');
    dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-label',title);
    const head=el('header','editor-heading'),heading=el('h2','',title),host=el('div','editor-content'),foot=el('footer','editor-footer'),message=el('p','editor-status'),actions=el('div','dialog-actions');message.setAttribute('role','status');head.append(heading);foot.append(message,actions);dialog.append(head,host,foot);overlay.append(dialog);document.body.append(overlay);panel.inert=true;
    let closed=false;
    const done=async()=>{if(closed)return;closed=true;cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;await closeSheet(overlay,'.vision-dialog');overlay.remove();panel.inert=false;if(activeEditor?.overlay===overlay)activeEditor=null;if(opener?.isConnected)opener.focus();};
    activeEditor={overlay,close:done};
