  const createProfileEditor=()=>openEditor('Create a profile',(host,actions,done)=>{const name=input('Profile name','',{parent:host,description:'Letters, numbers, hyphens or underscores.'}),description=input('Description','',{parent:host});let inherit=true;toggle('Use current account settings',true,v=>{inherit=v;},{parent:host,description:'Copy the account and tools. Start with an empty conversation.'});button('Create profile',async()=>{await api('desktop/profiles',{action:'create',name:name.value.toLowerCase().trim(),description:description.value,inherit});await done();window.dispatchEvent(new Event('vision:profiles-updated'));await select('Profiles');notice('Profile created.');},actions,'primary');});
  const descriptions={Profiles:'Your spaces, each with its own memory and conversation.',Model:'Choose the intelligence behind Vision.',Voice:'Your voice, microphone and camera.',Conversation:'Your main conversation and saved history.',Instructions:'Tell Vision how you want it to work.',Personality:'Set the tone and depth of its replies.',Memory:'What Vision remembers, written for you to read.',Skills:'Explore the skills available to your assistant.',Tools:'Choose what Vision can use.',Connectors:'Manage connections to your services and tools.',Schedules:'Create and manage tasks that run later.',Journey:'How your assistant has learned over time.',System:'Real information from this Windows computer.',Security:'Protect access to your Vision workspace.',Preferences:'Fine-tune how your assistant behaves.',Actions:'Every native action, connected to the actual engine.'};
