      choose('Wait after your input',[[1,'1 second'],[3,'3 seconds'],[5,'5 seconds'],[10,'10 seconds'],[15,'15 seconds']],data.quiet_seconds,v=>api('app-control/settings',{quiet_seconds:Number(v)}),{parent:controls});
      const sessions=await api('app-control/sessions');const list=section('Open application sessions');
