      button('Settings',()=>openEditor('Camera settings',async(host,actions,done)=>{const devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput');let cameraId=devices[0]?.deviceId||'';if(devices.length)choose('Camera source',devices.map((d,i)=>[d.deviceId,d.label||'Camera '+(i+1)]),cameraId,v=>cameraId=v,{parent:host});const video=el('video','camera-preview');video.autoplay=true;video.muted=true;video.playsInline=true;video.hidden=true;host.append(video);const controls=el('div','document-actions');host.append(controls);button('Open preview',async()=>{cameraStream?.getTracks().forEach(t=>t.stop());const stream=await navigator.mediaDevices.getUserMedia({video:cameraId?{deviceId:{exact:cameraId}}:true,audio:false});if(!host.isConnected){stream.getTracks().forEach(t=>t.stop());return;}cameraStream=stream;video.srcObject=stream;video.hidden=false;await video.play();},controls);button('Stop preview',()=>{cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;video.srcObject=null;video.hidden=true;},controls);button('Done',done,actions);}),row('Camera','Choose a source or open its preview',speech));
