    Conversation:async()=>{const s=section('Main conversation');const title=await rpc('session.title');const field=input('Title',title.title||'',{parent:s});button('Save title',async()=>{await rpc('session.title',{title:field.value});notice('Conversation title saved.');},s,'primary');button('New conversation',async()=>{if(await modal('Start a new conversation?',{text:'The current conversation stays in your history.',confirm:'Start new'})){await api('settings/command',{command:'/new'});await select('Conversation');}},s);button('Clear conversation',async()=>{if(await modal('Clear this conversation?',{text:'Start with a clean main chat.',confirm:'Clear',danger:true})){await api('settings/command',{command:'/clear'});await select('Conversation');}},s);const list=section('History');const data=await rpc('session.list',{limit:10000});if(!data.sessions?.length)empty('No saved conversations','Your conversations appear here as you use Vision.',list);for(const session of data.sessions||[]){const c=card(session.title||'Untitled conversation',session.preview||'',list);c.card.append(el('small','card-detail',(session.message_count||0)+' messages'+(session.started_at?' · '+new Date(session.started_at*1000).toLocaleDateString():'')));button('Open',async()=>{await api('settings/command',{command:'/resume '+session.id});await close();},c.head);}},
    Instructions:async()=>{const data=await api('settings/prompt');const s=section('Custom instructions','Vision’s desktop integration stays enabled alongside your instructions.');const field=input('How should Vision respond?',data.prompt,{parent:s,multiline:true});field.classList.add('document-editor');button('Save instructions',async()=>{await api('settings/prompt',{prompt:field.value});notice('Instructions updated for this conversation.');},s,'primary');},
