    Memory:async()=>{const data=await api('settings/memory');if(!data.files.length)empty('A fresh memory','Vision will build its memory as you work together.');for(const file of data.files){const basename=file.name.split(/[\\/]/).pop().toLowerCase();const title=basename.startsWith('user')?'About you':basename.startsWith('memory')?'Memory':pretty(basename.replace(/\.[^.]+$/,''));const c=card(title,'',body),document=el('div','memory-document');VisionRichText.render(document,file.content);c.card.append(document);button('Edit',async()=>{const editor=el('textarea','document-editor');editor.value=file.content;document.replaceChildren(editor);const actions=el('div','document-actions');document.append(actions);button('Save memory',async()=>{await api('settings/memory',{name:file.name,content:editor.value});await select('Memory');notice('Memory updated.');},actions,'primary');button('Cancel',()=>select('Memory'),actions);editor.focus();},c.head);}},
