    Connectors:async()=>{const cfg=await loadConfig();const servers=cfg.mcp_servers||{};if(!Object.keys(servers).length)empty('No connectors yet','Connect a local tool server or a remote service.');for(const [name,server]of Object.entries(servers)){const s=section(pretty(name));configControls(server,s);button('Save connector',saveConfig,s,'primary');button('Remove connector',async()=>{if(await modal('Remove '+pretty(name)+'?',{text:'This disconnects the service from Vision.',confirm:'Remove',danger:true})){delete servers[name];cfg.mcp_servers=servers;await saveConfig();await select('Connectors');}},s,'danger');}const add=section('Add a connector');const name=input('Name','',{parent:add}),endpoint=input('Server URL or executable','',{parent:add}),args=input('Arguments','',{parent:add,description:'One argument per line.',multiline:true});button('Add connector',async()=>{if(!name.value.trim()||!endpoint.value.trim())throw Error('Enter a name and server address.');const value=endpoint.value.trim();servers[name.value.trim()]=/^https?:\/\//.test(value)?{url:value}:{command:value,args:args.value.split('\n').filter(Boolean)};cfg.mcp_servers=servers;await saveConfig();await select('Connectors');},add,'primary');},
