    Preferences:async()=>{const cfg=await loadConfig();for(const [key,value] of Object.entries(cfg)){if(['model','providers','mcp_servers','personalities','custom_prompt'].includes(key))continue;const s=section(pretty(key));if(value&&typeof value==='object'&&!Array.isArray(value))configControls(value,s);else if(typeof value==='boolean')toggle(pretty(key),value,v=>{cfg[key]=v;},{parent:s});else input(pretty(key),value,{parent:s,type:typeof value==='number'?'number':'text',onchange:v=>cfg[key]=v});}button('Save preferences',saveConfig,body,'primary');},
    Actions:async()=>{const data=await api('commands');let commands=data.all||data.commands||data.pairs||[];if(!Array.isArray(commands))commands=(data.categories||[]).flatMap(c=>c.commands||c.items||[]);const search=input('Find an action');const list=el('div','native-actions');body.append(list);const pagesByCommand={model:'Model',models:'Model',memory:'Memory',skills:'Skills',tools:'Tools',toolsets:'Tools',cron:'Schedules',schedule:'Schedules',personality:'Personality',prompt:'Instructions',profile:'Profiles',profiles:'Profiles',journey:'Journey',status:'System',whoami:'Profiles',battery:'System',sessions:'Conversation',history:'Conversation',new:'Conversation',clear:'Conversation',title:'Conversation',reasoning:'Personality',config:'Preferences'};for(const item of commands){const name=Array.isArray(item)?item[0]:item.name||item.command;const description=Array.isArray(item)?item[1]:item.description;if(!name)continue;const raw=name.replace(/^\//,''),c=card(pretty(raw),description||'',list);c.card.dataset.search=(raw+' '+description).toLowerCase();button(pagesByCommand[raw]?'Open':'Run',async()=>{if(pagesByCommand[raw]){await select(pagesByCommand[raw]);return;}const arg=await modal(pretty(raw),{text:description||'Run this native action.',input:true,confirm:'Run'});if(arg===null)return;const result=await api('settings/command',{command:'/'+raw+(arg?' '+arg:'')});if(result.output){const text=VisionRichText.strip(result.output).replace(/[┌┐└┘─│├┤┬┴┼╭╮╰╯]/g,'');const content=section(pretty(raw));VisionRichText.render(content,text);}notice('Action completed.');},c.head);}search.oninput=()=>{for(const c of list.children)c.hidden=!c.dataset.search.includes(search.value.toLowerCase());};}
