  async function select(name){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;const version=++generation;current=name;body.replaceChildren();notice('');panel.querySelector('h1').textContent=name;panel.querySelector('.settings-heading p').textContent=descriptions[name];for(const b of nav.querySelectorAll('button')){b.setAttribute('aria-current',String(b.dataset.page===name));b.disabled=true;}const loading=el('div','settings-loading','Loading your settings…');body.append(loading);try{await pages[name]();}catch(e){if(version===generation)notice(e.message,true);}finally{loading.remove();if(version===generation)for(const b of nav.querySelectorAll('button'))b.disabled=false;}}
  const pageOrder=Object.keys(pages).filter(name=>name!=='Application control');pageOrder.splice(pageOrder.indexOf('Tools')+1,0,'Application control');
  for(const name of pageOrder){const b=el('button','settings-nav-item');b.dataset.page=name;b.innerHTML=svg(icons[name]);b.append(el('span','',name));b.onclick=()=>select(name);nav.append(b);}
  async function open(name='Profiles'){returnFocus=document.activeElement;await Promise.all([openSheet(layer),select(name)]);panel.querySelector('.settings-close').focus();}
  async function close(){if(activeEditor)await activeEditor.close();generation++;cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;await closeSheet(layer);returnFocus?.focus();}
  panel.querySelector('.settings-close').onclick=close;panel.querySelector('.settings-reload').onclick=()=>select(current);layer.onkeydown=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const items=[...panel.querySelectorAll('button:not(:disabled),input,textarea,[tabindex="0"]')].filter(n=>n.offsetParent!==null);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}};
  for(const parent of [document.querySelector('.controls'),document.querySelector('.workspace-header')]){const b=el('button','settings-toggle');b.title='Settings';b.setAttribute('aria-label','Open Vision settings');b.innerHTML=svg('m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3ZM9 12a3 3 0 1 0 6 0 3 3 0 0 0-6 0');b.onclick=()=>open();parent.append(b);}
  window.VisionSettings={open,close,createProfile:()=>createProfileEditor()};
